  `valor` decimal(8,2) DEFAULT NULL,
  `status` int(11) DEFAULT NULL,
  `data_pago` date DEFAULT NULL,
  `plano_contas_id` int(11) NOT NULL,
  `fornecedores_id` int(11) NOT NULL,
  `forma_pgto` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_contas_pagar_plano_contas1_idx` (`plano_contas_id`),
  KEY `fk_contas_pagar_fornecedores1_idx` (`fornecedores_id`),
  CONSTRAINT `fk_contas_pagar_fornecedores1` FOREIGN KEY (`fornecedores_id`) REFERENCES `fornecedores` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_contas_pagar_plano_contas1` FOREIGN KEY (`plano_contas_id`) REFERENCES `plano_contas` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB AUTO_INCREMENT=6206 DEFAULT CHARSET=utf8;
